create table survey (
StartDate		timestamp	not null,     -- from qualtrics
EndDate			timestamp	not null,     -- from qualtrics
ResponseType		varchar(30)	not null, -- from qualtrics
IPAddress		varchar(20),              -- from qualtrics
Progress		integer		not null,     -- from qualtrics
DurationSec		integer		not null,     -- from qualtrics
Finished		varchar(5)	not null,     -- from qualtrics
RecordedDate		timestamp	not null, -- from qualtrics
ResponseID		varchar(30)	not null,     -- from qualtrics
RecipientLastName	varchar(40),          -- from qualtrics
RecipientFirstName	varchar(40),          -- from qualtrics
RecipientEmail		varchar(40),          -- from qualtrics
ExternalDataReference	varchar(40),      -- from qualtrics
LocationLatitude	float,                -- from qualtrics
LocationLongitude	float,                -- from qualtrics
DistributionChannel	varchar(40),          -- from qualtrics
UserLanguage		varchar(2),           -- from qualtrics
StThomasEmail		varchar(50),          -- from user input
ClassSection		varchar(10),
AlternateOSes		varchar(30),          -- What operating system do you have access to?
DefaultOS		varchar(20),              -- What operating system do you usually use?
TerminalAvailable		varchar(40),      -- Do you have access to bash terminal?
-- slider survey questions: On a scale from 0 to 100, how knowledgeable are you following?
databases		integer,
commandline		integer,
spreadsheets		integer,
python			integer,
webprogramming		integer,
cloud			integer,
git			integer,
logic			integer,
PastDbExperience	varchar(400), -- essay/qualitative question: describe your past database experience
constraint 		survey_pk	primary key(ResponseID, stthomasemail)
);
